-- Generated by lib/map-zones.ts (#745, ARC on #751). Seeds the seven missing map-design 6.2 rare node types; an occupied target falls back to the nearest eligible square; fails unless all seven exist.
-- Eligible: Commons, or an unowned Wildlands square that the same UPDATE rezones to Commons; never Heartland or Frontier.
UPDATE world_squares SET resource='Ironroot', zone='commons' WHERE NOT EXISTS (SELECT 1 FROM world_squares WHERE resource='Ironroot') AND (x,y) = (SELECT x,y FROM world_squares WHERE zone IN ('commons','wildlands') AND owner IS NULL AND resource IS NULL AND feature IS NULL AND x BETWEEN 10 AND 14 AND y BETWEEN 4 AND 8 AND NOT (x BETWEEN 2 AND 8 AND y BETWEEN 1 AND 7) AND NOT (x BETWEEN 1 AND 7 AND y BETWEEN 10 AND 16) AND NOT (x BETWEEN 15 AND 21 AND y BETWEEN 1 AND 7) AND NOT (x BETWEEN 9 AND 15 AND y BETWEEN 11 AND 17) AND NOT (x BETWEEN 23 AND 29 AND y BETWEEN 14 AND 20) AND NOT (x BETWEEN 22 AND 28 AND y BETWEEN 0 AND 6) AND NOT (x BETWEEN 0 AND 6 AND y BETWEEN 17 AND 23) AND NOT (x BETWEEN 16 AND 22 AND y BETWEEN 8 AND 14) AND NOT (x BETWEEN 23 AND 29 AND y BETWEEN 7 AND 13) AND NOT (x BETWEEN 16 AND 22 AND y BETWEEN 15 AND 21) ORDER BY CASE WHEN x=12 AND y=5 THEN 0 WHEN zone='commons' THEN 1 ELSE 2 END, CASE WHEN abs(x-12)>abs(y-5) THEN abs(x-12) ELSE abs(y-5) END, (x-12)*(x-12)+(y-5)*(y-5), y, x LIMIT 1);
