-- Post-seed check: unless all seven types sit on Commons squares, this inserts a row with x NULL. world_squares.x is NOT NULL, so the insert fails and so does the migration (SQLite and Postgres; DML only, no RAISE needed).
INSERT INTO world_squares (x,y,zone,owner,terrain,resource,feature) SELECT NULL,NULL,'wildlands',NULL,'rare node check failed',NULL,NULL WHERE (SELECT COUNT(DISTINCT resource) FROM world_squares WHERE zone='commons' AND resource IN ('Ironroot','Sunglass','Geotherm core','Frostcore','Hazequartz','Heartwood','Stormcells')) < 7;
